function mod(a, b) {
  return a - ~~(a / b) * b;
}

function div(a, b) {
  return ~~(a / b);
}

function gregorian_to_jd(gy, gm, gd) {
  var d =
    div((gy + div(gm - 8, 6) + 100100) * 1461, 4) +
    div(153 * mod(gm + 9, 12) + 2, 5) +
    gd -
    34840408;

  d = d - div(div(gy + 100100 + div(gm - 8, 6), 100) * 3, 4) + 752;
  return d;
}

function jd_to_gregorian(jdn) {
  var j = 4 * jdn + 139361631;
  var i;
  var day;
  var month;
  var year;

  j = j + div(div(4 * jdn + 183187720, 146097) * 3, 4) * 4 - 3908;
  i = div(mod(j, 1461), 4) * 5 + 308;
  day = div(mod(i, 153), 5) + 1;
  month = mod(div(i, 153), 12) + 1;
  year = div(j, 1461) - 100100 + div(8 - month, 6);

  return [year, month, day];
}

function leap_gregorian(gy) {
  return gy % 4 === 0 && (gy % 100 !== 0 || gy % 400 === 0);
}

function leap_islamic(year) {
  return (11 * year + 14) % 30 < 11;
}

function islamic_to_jd(year, month, day) {
  return day + Math.ceil(29.5 * (month - 1)) + (year - 1) * 354 + div(3 + 11 * year, 30) + ISLAMIC_EPOCH - 1;
}

function jd_to_islamic(jd) {
  var year;
  var month;
  var day;

  jd = Math.floor(jd) + 0.5;
  year = Math.floor((30 * (jd - ISLAMIC_EPOCH) + 10646) / 10631);
  month = Math.min(12, Math.ceil((jd - (29 + islamic_to_jd(year, 1, 1))) / 29.5) + 1);
  day = jd - islamic_to_jd(year, month, 1) + 1;

  return [year, month, day];
}

var PERSIAN_BREAKS = [-61, 9, 38, 199, 426, 686, 756, 818, 1111, 1181, 1210, 1635, 2060, 2097, 2192, 2262, 2324, 2394, 2456, 3178];

function jalCal(jy) {
  var bl = PERSIAN_BREAKS.length;
  var gy = jy + 621;
  var leapJ = -14;
  var jp = PERSIAN_BREAKS[0];
  var jm;
  var jump = 0;
  var leap;
  var leapG;
  var march;
  var n;
  var i;

  if (jy < jp || jy >= PERSIAN_BREAKS[bl - 1]) {
    throw new Error("Invalid Jalali year " + jy);
  }

  for (i = 1; i < bl; i++) {
    jm = PERSIAN_BREAKS[i];
    jump = jm - jp;
    if (jy < jm) {
      break;
    }
    leapJ = leapJ + div(jump, 33) * 8 + div(mod(jump, 33), 4);
    jp = jm;
  }

  n = jy - jp;
  leapJ = leapJ + div(n, 33) * 8 + div(mod(n, 33) + 3, 4);

  if (mod(jump, 33) === 4 && jump - n === 4) {
    leapJ += 1;
  }

  leapG = div(gy, 4) - div((div(gy, 100) + 1) * 3, 4) - 150;
  march = 20 + leapJ - leapG;

  if (jump - n < 6) {
    n = n - jump + div(jump + 4, 33) * 33;
  }

  leap = mod(mod(n + 1, 33) - 1, 4);
  if (leap === -1) {
    leap = 4;
  }

  return {
    leap: leap,
    gy: gy,
    march: march
  };
}

function leap_persian(jy) {
  return jalCal(jy).leap === 0;
}

function persian_to_jd(jy, jm, jd) {
  var r = jalCal(jy);
  return gregorian_to_jd(r.gy, 3, r.march) + (jm - 1) * 31 - div(jm, 7) * (jm - 7) + jd - 1;
}

function jd_to_persian(jd) {
  var g = jd_to_gregorian(jd);
  var jy = g[0] - 621;
  var r = jalCal(jy);
  var jdn1f = gregorian_to_jd(r.gy, 3, r.march);
  var jd1;
  var jm;
  var k = jd - jdn1f;

  if (k >= 0) {
    if (k <= 185) {
      jm = 1 + div(k, 31);
      jd1 = mod(k, 31) + 1;
      return [jy, jm, jd1];
    }
    k -= 186;
  } else {
    jy -= 1;
    k += 179;
    if (r.leap === 1) {
      k += 1;
    }
  }

  jm = 7 + div(k, 30);
  jd1 = mod(k, 30) + 1;
  return [jy, jm, jd1];
}

function normalizeJalaliDateParts(year, monthIndex, day) {
  var yearOffset = Math.floor(monthIndex / 12);
  var normalizedMonth = ((monthIndex % 12) + 12) % 12;
  var g;

  year += yearOffset;

  g = jd_to_gregorian(persian_to_jd(year, normalizedMonth + 1, 1) + day - 1);
  return {
    gregorian: g,
    jalali: jd_to_persian(gregorian_to_jd(g[0], g[1], g[2]))
  };
}

function JalaliDate(year, month, day) {
  var gregorianDate;
  var jalaliDate;

  function syncFromGregorian(date) {
    var candidate = date && date.getGregorianDate ? new Date(date.getGregorianDate().getTime()) : new Date(date);
    var jalali;

    if (isNaN(candidate.getTime())) {
      candidate = new Date();
    }

    gregorianDate = new Date(candidate.getTime());
    jalali = jd_to_persian(gregorian_to_jd(
      gregorianDate.getFullYear(),
      gregorianDate.getMonth() + 1,
      gregorianDate.getDate()
    ));
    jalaliDate = [jalali[0], jalali[1] - 1, jalali[2]];
    return this;
  }

  function syncFromJalali(jy, jm, jd) {
    var normalized = normalizeJalaliDateParts(jy, jm, jd);
    gregorianDate = new Date(normalized.gregorian[0], normalized.gregorian[1] - 1, normalized.gregorian[2]);
    jalaliDate = [normalized.jalali[0], normalized.jalali[1] - 1, normalized.jalali[2]];
    return this;
  }

  if (isNaN(parseInt(year, 10)) || isNaN(parseInt(month, 10)) || isNaN(parseInt(day, 10))) {
    syncFromGregorian.call(this, year);
  } else {
    syncFromJalali.call(this, parseInt(year, 10), parseInt(month, 10), parseInt(day, 10));
  }

  this.getGregorianDate = function () {
    return new Date(gregorianDate.getTime());
  };

  this.setFullDate = function (date) {
    return syncFromGregorian.call(this, date);
  };

  this.setMonth = function (newMonth) {
    return syncFromJalali.call(this, jalaliDate[0], newMonth, jalaliDate[2]);
  };

  this.setDate = function (newDay) {
    return syncFromJalali.call(this, jalaliDate[0], jalaliDate[1], newDay);
  };

  this.getFullYear = function () {
    return jalaliDate[0];
  };

  this.getMonth = function () {
    return jalaliDate[1];
  };

  this.getDate = function () {
    return jalaliDate[2];
  };

  this.toString = function () {
    return jalaliDate.join(",");
  };

  this.getDay = function () {
    return gregorianDate.getDay();
  };

  this.getHours = function () {
    return gregorianDate.getHours();
  };

  this.getMinutes = function () {
    return gregorianDate.getMinutes();
  };

  this.getSeconds = function () {
    return gregorianDate.getSeconds();
  };

  this.getTime = function () {
    return gregorianDate.getTime();
  };

  this.getTimeZoneOffset = function () {
    return gregorianDate.getTimezoneOffset();
  };

  this.getYear = function () {
    return jalaliDate[0] % 100;
  };

  this.setHours = function (hours) {
    gregorianDate.setHours(hours);
    return syncFromGregorian.call(this, gregorianDate);
  };

  this.setMinutes = function (minutes) {
    gregorianDate.setMinutes(minutes);
    return syncFromGregorian.call(this, gregorianDate);
  };

  this.setSeconds = function (seconds) {
    gregorianDate.setSeconds(seconds);
    return syncFromGregorian.call(this, gregorianDate);
  };

  this.setMilliseconds = function (milliseconds) {
    gregorianDate.setMilliseconds(milliseconds);
    return syncFromGregorian.call(this, gregorianDate);
  };
}

var GREGORIAN_EPOCH = 1721425.5;
var ISLAMIC_EPOCH = 1948439.5;
var PERSIAN_EPOCH = 1948320.5;

jQuery(function ($) {
  $.datepicker.regional.fa = {
    calendar: JalaliDate,
    closeText: "بستن",
    prevText: "قبل",
    nextText: "بعد",
    currentText: "امروز",
    monthNames: ["فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور", "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"],
    monthNamesShort: ["فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور", "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"],
    dayNames: ["یکشنبه", "دوشنبه", "سه شنبه", "چهارشنبه", "پنجشنبه", "جمعه", "شنبه"],
    dayNamesShort: ["یک", "دو", "سه", "چهار", "پنج", "جمعه", "شنبه"],
    dayNamesMin: ["ی", "د", "س", "چ", "پ", "ج", "ش"],
    weekHeader: "ه",
    dateFormat: "dd/mm/yy",
    firstDay: 6,
    isRTL: true,
    showMonthAfterYear: false,
    yearSuffix: "",
    calculateWeek: function (date) {
      var weekDate = new JalaliDate(date.getFullYear(), date.getMonth(), date.getDate() + (date.getDay() || 7) - 3);
      return Math.floor(Math.round((weekDate.getTime() - new JalaliDate(weekDate.getFullYear(), 0, 1).getTime()) / 86400000) / 7) + 1;
    }
  };

  $.datepicker.setDefaults($.datepicker.regional.fa);
});
